from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]; o=json.loads((ROOT/'outputs/audit_summary.json').read_text(encoding='utf-8')); c=o['checkpoint']; q=o['quality']; clk=o['clock']
body=f'''<!doctype html><html><head><meta charset="utf-8"><title>Where the Clock Starts — Engineering Demo</title><style>body{{font-family:system-ui;max-width:980px;margin:40px auto;padding:0 20px;line-height:1.5}}.card{{border:1px solid #ddd;border-radius:12px;padding:18px;margin:14px 0}}</style></head><body><h1>Where the Clock Starts — Research Engineering Demonstration</h1><p>All records are synthetic.</p><div class="card"><h2>Checkpoint accounting</h2><p>Parent: {c['parent_rows']} · Primary: {c['primary_rows']} · Process: {c['process_rows']} · Payment: {c['payment_rows']}</p></div><div class="card"><h2>Process-clock QA</h2><p>Eligible: {clk['eligible_rows']} · Flagged: {clk['clock_flagged']} · Restricted: {clk['clock_restricted']}</p><p>Chronology failures: {clk['chronology_failures']}</p></div><div class="card"><h2>Relational QA</h2><p>Status: <strong>{html.escape(q['status'])}</strong> · Checks: {q['checks']} · Failures: {q['failures']}</p></div><div class="card"><h2>Boundary</h2><p>Engineering demonstration only. No private empirical result is included.</p></div></body></html>'''
(ROOT/'outputs/dashboard.html').write_text(body,encoding='utf-8'); print('DASHBOARD=PASS')
